"""Dependency records and probe input normalization."""

from dataclasses import dataclass


@dataclass(frozen=True)
class Dependency:
    name: str
    required_for_readiness: bool
    healthy: bool
    latency_ms: int = 0

    def status_label(self) -> str:
        if self.healthy:
            return "ok"
        if self.required_for_readiness:
            return "down"
        return "degraded"


def dependency_from_mapping(payload: dict) -> Dependency:
    name = str(payload.get("name", "")).strip()
    if not name:
        raise ValueError("dependency name is required")
    return Dependency(
        name=name,
        required_for_readiness=bool(payload.get("required_for_readiness", True)),
        healthy=bool(payload.get("healthy", False)),
        latency_ms=int(payload.get("latency_ms", 0)),
    )


def normalize_dependencies(items) -> list[Dependency]:
    normalized: list[Dependency] = []
    for item in items:
        if isinstance(item, Dependency):
            normalized.append(item)
        else:
            normalized.append(dependency_from_mapping(item))
    return normalized


def summarize_dependencies(items) -> dict[str, str]:
    return {dep.name: dep.status_label() for dep in normalize_dependencies(items)}

# Operational helpers used by this challenge domain.
DEPENDENCIES_DOMAIN_TERMS = ('probe', 'dependency', 'traffic', 'diagnostic')

class DependenciesLedger:
    """In-memory notes for local operational decisions."""

    def __init__(self, owner="system", metadata=None):
        self.owner = owner
        self.metadata = dict(metadata or {})
        self.events = []

    def record(self, event, **details):
        item = {"event": str(event), "details": dict(details)}
        self.events.append(item)
        self.metadata[item["event"]] = self.metadata.get(item["event"], 0) + 1
        return item

    def snapshot(self):
        return {"owner": self.owner, "metadata": dict(self.metadata), "events": list(self.events)}

def dependencies_compact_metadata(metadata):
    """Return public probe metadata without empty values."""
    clean = {}
    for name, value in dict(metadata or {}).items():
        if value in (None, "", [], {}):
            continue
        clean[str(name)] = value
    return clean

def dependencies_merge_context(base, extra):
    """Merge dependency context without mutating caller-owned dictionaries."""
    merged = dependencies_compact_metadata(base)
    for name, value in dict(extra or {}).items():
        if value is not None:
            merged[str(name)] = value
    return merged

def dependencies_labels(records, key="name"):
    """Extract labels for traffic diagnostics."""
    labels = []
    for record in records or []:
        value = record.get(key) if isinstance(record, dict) else getattr(record, key, None)
        if value is not None:
            labels.append(str(value))
    return labels

def dependencies_group_by_status(records, key="status"):
    """Group diagnostic records for operator summaries."""
    grouped = {}
    for record in records or []:
        status = record.get(key, "unknown") if isinstance(record, dict) else getattr(record, key, "unknown")
        grouped.setdefault(str(status), []).append(record)
    return grouped

def dependencies_summary(records, key="status"):
    """Count dependencies records by status."""
    return {name: len(items) for name, items in dependencies_group_by_status(records, key).items()}

