    deps = normalize_dependencies(dependencies)
    alive = process_started and all(dep.healthy for dep in deps)
    return {
        "probe": "liveness",
        "status": "live" if alive else "unhealthy",
        "dependencies": summarize_dependencies(deps),
    }


